package io.github.ningpp.compat;

import java.lang.reflect.Array;
import java.util.ArrayList;
import java.util.List;

/** Replacement for System.Runtime.InteropServices.MemoryMarshal (generated by CSharpToJava converter). */
public class MemoryMarshal {
    /**
     * The prefix of a UTF-16 span that .NET's {@code JsonWriterHelper.ToUtf8} is able to encode.
     *
     * <p>.NET's {@code Utf8JsonWriter.WriteCommentValue} deliberately skips validation ("invalid text
     * allowed"), but the encoder itself stops at the first unpaired surrogate and reports only the
     * bytes it managed to write - the REST OF THE COMMENT IS SILENTLY DROPPED. The SDK's own test says
     * so: {@code Utf8JsonWriterTests.WriteCommentsInvalidTextAllowed} writes
     * {@code "comment is / * valid even with unpaired surrogate \udc00 this part no longer visible"}
     * while its expected string is built from the SHORT literal
     * {@code "comment is / * valid even with unpaired surrogate "}.</p>
     *
     * <p>The Java port of {@code ToUtf8} replaces the bad unit with U+FFFD and keeps going, so the
     * actual output carried {@code \uFFFD this part no longer visible} and the four theory rows
     * failed. Truncating the comment before it reaches the encoder reproduces the .NET result without
     * touching the translated state machine.</p>
     */
    public static ReadOnlySpan<Character> truncateAtInvalidUtf16(ReadOnlySpan<Character> value) {
        if (value == null) {
            return null;
        }
        int length = value.getLength();
        for (int i = 0; i < length; i++) {
            char ch = value.get(i);
            if (Character.isHighSurrogate(ch)) {
                if (i + 1 >= length || !Character.isLowSurrogate(value.get(i + 1))) {
                    return value.slice(0, i);
                }
                i++;
            } else if (Character.isLowSurrogate(ch)) {
                return value.slice(0, i);
            }
        }
        return value;
    }

    /**
     * Mirrors C# MemoryMarshal.AsBytes — reinterprets numeric elements as bytes
     * (4 bytes per element) and character elements as UTF-16 little-endian bytes
     * (2 bytes per element), matching ReadOnlySpan&lt;char&gt; layout on .NET.
     */
    @SuppressWarnings("unchecked")
    public static ReadOnlySpan<Integer> asBytes(ReadOnlySpan span) {
        int len = span.length();
        if (len > 0 && span.get(0) instanceof Character) {
            Integer[] bytes = new Integer[len * 2];
            for (int i = 0; i < len; i++) {
                int cp = (Character) span.get(i);
                bytes[i * 2] = cp & 0xFF;
                bytes[i * 2 + 1] = (cp >>> 8) & 0xFF;
            }
            return new ReadOnlySpan<>(bytes);
        }
        Integer[] bytes = new Integer[len * 4];
        for (int i = 0; i < len; i++) {
            int cp = ((Number) span.get(i)).intValue();
            bytes[i * 4] = (cp >>> 24) & 0xFF;
            bytes[i * 4 + 1] = (cp >>> 16) & 0xFF;
            bytes[i * 4 + 2] = (cp >>> 8) & 0xFF;
            bytes[i * 4 + 3] = cp & 0xFF;
        }
        return new ReadOnlySpan<>(bytes);
    }

    /** Overload for the converter's mutable Span re-wrapping of char[].AsSpan. */
    public static ReadOnlySpan<Integer> asBytes(Span span) {
        return asBytes(span.asReadOnlySpan());
    }

    /** Mirrors C# MemoryMarshal.Read&lt;int&gt;(ReadOnlySpan&lt;byte&gt;) — little-endian 4-byte read. */
    public static int read(ReadOnlySpan<Integer> span) {
        int value = 0;
        int count = Math.min(4, span.length());
        for (int i = 0; i < count; i++) {
            value |= (span.get(i) & 0xFF) << (i * 8);
        }
        return value;
    }

    /** Mirrors C# MemoryMarshal.Read&lt;long&gt;(ReadOnlySpan&lt;byte&gt;) — little-endian 8-byte read. */
    public static long readLong(ReadOnlySpan<Integer> span) {
        long value = 0;
        int count = Math.min(8, span.length());
        for (int i = 0; i < count; i++) {
            value |= (long) (span.get(i) & 0xFF) << (i * 8);
        }
        return value;
    }

    /**
     * Mirrors C# MemoryMarshal.GetReference&lt;T&gt;(Span&lt;T&gt;): Java has no ref
     * returns, so this yields the first element by value (call sites read it).
     */
    public static <T> T getReference(Span<T> span) {
        return span.get(0);
    }

    /**
     * Mirrors C# MemoryMarshal.GetReference&lt;T&gt;(ReadOnlySpan&lt;T&gt;): Java has no ref
     * returns, so this yields the first element by value (call sites read it).
     * Returns {@code null} for an empty span (C# returns a ref to the backing buffer,
     * which is unsafe to dereference; returning null is the safe Java equivalent).
     */
    public static <T> T getReference(ReadOnlySpan<T> span) {
        return span.length() > 0 ? span.get(0) : null;
    }

    /**
     * Mirrors C# MemoryMarshal.CreateSpan&lt;char&gt;(ref char reference, int length):
     * the converter lowers the ref char argument into a CharHolder, so unwrap the
     * holder's value to seed a char-typed span (CharConverter.Write/WriteWithQuotes
     * call Utf8JsonWriter.writeStringValue/writePropertyName with it).
     */
    public static Span<Character> createSpan(CharHolder first, int length) {
        Character[] arr = new Character[length];
        if (length > 0 && first != null) {
            arr[0] = first.value;
        }
        return new Span<>(arr);
    }

    /**
     * Mirrors C# MemoryMarshal.CreateSpan&lt;T&gt;(ref T reference, int length):
     * creates a Span of {@code length} elements seeded from the first field of a
     * generated struct/class (e.g. FourStackStrings.Item1). Subsequent fields are
     * read via reflection so stackalloc-like multi-field structs work.
     */
    @SuppressWarnings("unchecked")
    public static <T> Span<T> createSpan(T first, int length) {
        Object[] arr = new Object[length];
        if (length > 0) {
            arr[0] = first;
        }
        if (length > 1 && first != null) {
            java.lang.reflect.Field[] fields = first.getClass().getFields();
            // arr[0] already holds Item1 (the `first` argument); arr[i] maps to fields[i]
            // (Item2..ItemN) since getFields() returns the public fields in declaration order.
            for (int i = 1; i < length && i < fields.length; i++) {
                try {
                    arr[i] = fields[i].get(first);
                } catch (IllegalAccessException e) {
                    arr[i] = null;
                }
            }
        }
        return new Span<>((T[]) arr);
    }

    /**
     * Mirrors MemoryMarshal.Read&lt;T&gt;(ReadOnlySpan&lt;byte&gt;) for struct targets.
     *
     * <p>Java value classes (JEP 401) forbid mutating their (implicitly final) fields
     * through deep reflection — {@code Field.set}, {@code VarHandle.set} and
     * {@code Unsafe.putInt} all fail on a value object — so for value classes the
     * instance is rebuilt through a constructor (the only sanctioned creation path)
     * and accepted when it re-encodes to the very bytes being read. Regular classes
     * keep the reflective field-write path.</p>
     */
    public static <T> T read(ReadOnlySpan<Integer> span, Class<T> type) {
        if (type.isValue()) {
            T value = readValueClass(span, type);
            if (value != null) {
                return value;
            }
            throw new UnsupportedOperationException(
                "MemoryMarshal.read cannot reconstruct value class " + type.getName()
                    + " from the given byte span: no constructor reproduces the encoded layout.");
        }
        try {
            var ctor = type.getDeclaredConstructor();
            ctor.setAccessible(true);
            T instance = ctor.newInstance();
            readFields(instance, span);
            return instance;
        } catch (ReflectiveOperationException e) {
            return null;
        }
    }

    private static final int MAX_PROBE_COMBINATIONS = 1 << 13;

    /**
     * Rebuilds a value class instance from its encoded bytes. Field values are
     * decoded in declaration order exactly the way {@link #writeFields} lays them
     * out; then every constructor whose parameter count matches the field count is
     * tried: primitive parameters draw candidates from the decoded field values,
     * enum parameters from all enum constants, and the first combination whose
     * instance re-encodes to the same bytes wins. This recovers both canonical
     * constructors (StackRow(int, int)) and transformed ones (DbRow(JsonTokenType,
     * int, int) packing the token type with "{@code << 28}") without knowing the
     * transform.
     */
    @SuppressWarnings("unchecked")
    private static <T> T readValueClass(ReadOnlySpan<Integer> span, Class<T> type) {
        java.lang.reflect.Field[] fields = java.util.Arrays.stream(type.getDeclaredFields())
            .filter(f -> !java.lang.reflect.Modifier.isStatic(f.getModifiers()))
            .toArray(java.lang.reflect.Field[]::new);

        Object[] fieldValues = new Object[fields.length];
        int offset = 0;
        for (int i = 0; i < fields.length; i++) {
            fieldValues[i] = decodeFieldValue(span, offset, fields[i].getType());
            offset += sizeOfType(fields[i].getType());
        }

        // Priority 1: Try the "field-copy constructor" — one whose parameter
        // types exactly match the field types in declaration order.  This
        // constructor directly assigns each parameter to its corresponding
        // field, so the decoded field values produce the exact original
        // instance without needing encodesToSameBytes verification.
        Class<?>[] fieldTypes = new Class<?>[fields.length];
        for (int i = 0; i < fields.length; i++) {
            fieldTypes[i] = fields[i].getType();
        }
        for (var ctor : type.getDeclaredConstructors()) {
            if (ctor.getParameterCount() != fields.length) {
                continue;
            }
            Class<?>[] paramTypes = ctor.getParameterTypes();
            boolean exactMatch = true;
            for (int i = 0; i < paramTypes.length; i++) {
                if (paramTypes[i] != fieldTypes[i]
                    && TypeHelper.toWrapperType(paramTypes[i]) != TypeHelper.toWrapperType(fieldTypes[i])) {
                    exactMatch = false;
                    break;
                }
            }
            if (!exactMatch) {
                continue;
            }
            try {
                ctor.setAccessible(true);
                T instance = tryConstructValue(ctor, fieldValues, type);
                if (instance != null) {
                    return instance;
                }
            } catch (Exception ignored) {
            }
        }

        // Priority 2: Try all constructors with candidate combinations.
        for (var ctor : type.getDeclaredConstructors()) {
            if (ctor.getParameterCount() != fields.length) {
                continue;
            }
            try {
                ctor.setAccessible(true);
            } catch (Exception e) {
                continue;
            }
            List<Object[]> combinations = constructorCombinations(ctor.getParameterTypes(), fieldValues);
            if (combinations == null) {
                continue;
            }
            for (Object[] args : combinations) {
                T instance = tryConstructValue(ctor, args, type);
                if (instance != null && encodesToSameBytes(instance, span)) {
                    return instance;
                }
            }
        }

        // Priority 3: bit-shift-aware combinations for enum params.
        for (var ctor : type.getDeclaredConstructors()) {
            if (ctor.getParameterCount() != fields.length) {
                continue;
            }
            try {
                ctor.setAccessible(true);
            } catch (Exception e) {
                continue;
            }
            List<Object[]> combinations = constructorCombinationsWithBitShift(
                ctor.getParameterTypes(), fieldValues);
            if (combinations == null) {
                continue;
            }
            for (Object[] args : combinations) {
                T instance = tryConstructValue(ctor, args, type);
                if (instance != null && encodesToSameBytes(instance, span)) {
                    return instance;
                }
            }
        }
        return null;
    }

    /** Builds the candidate argument combinations for one constructor; null when unbounded. */
    private static List<Object[]> constructorCombinations(Class<?>[] paramTypes, Object[] fieldValues) {
        List<List<Object>> perParam = new ArrayList<>();
        long total = 1;
        for (Class<?> paramType : paramTypes) {
            List<Object> options = new ArrayList<>();
            if (paramType.isEnum()) {
                Object[] constants = paramType.getEnumConstants();
                if (constants == null || constants.length == 0) {
                    return null;
                }
                options.addAll(java.util.Arrays.asList(constants));
            } else {
                for (Object fv : fieldValues) {
                    if (fv != null && boxedTypeMatches(paramType, fv) && !options.contains(fv)) {
                        options.add(fv);
                    }
                }
                if (options.isEmpty()) {
                    options.add(defaultPrimitiveValue(paramType));
                }
            }
            total *= options.size();
            if (total > MAX_PROBE_COMBINATIONS) {
                return null;
            }
            perParam.add(options);
        }
        List<Object[]> combinations = new ArrayList<>();
        buildCombinations(perParam, 0, new Object[paramTypes.length], combinations);
        return combinations;
    }

    private static void buildCombinations(List<List<Object>> perParam, int index, Object[] current, List<Object[]> out) {
        if (index == perParam.size()) {
            out.add(current.clone());
            return;
        }
        for (Object option : perParam.get(index)) {
            current[index] = option;
            buildCombinations(perParam, index + 1, current, out);
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> T tryConstructValue(java.lang.reflect.Constructor<?> ctor, Object[] args, Class<T> type) {
        try {
            return type.cast(ctor.newInstance(args));
        } catch (Exception e) {
            return null;
        }
    }

    /** True when re-encoding {@code instance} reproduces the byte span exactly. */
    private static boolean encodesToSameBytes(Object instance, ReadOnlySpan<Integer> span) {
        Integer[] buffer = new Integer[span.length()];
        Span<Integer> writeSpan = new Span<>(buffer);
        writeValue(writeSpan, instance);
        // Only compare the bytes that were actually written (the struct's
        // encoded size).  The span may be longer than the struct (e.g.
        // MetadataDb.get passes a span from index to end-of-array), so
        // trailing bytes beyond the struct footprint should be ignored.
        int encodedSize = encodedByteSize(instance);
        for (int i = 0; i < encodedSize && i < span.length(); i++) {
            if (!java.util.Objects.equals(buffer[i], span.get(i))) {
                return false;
            }
        }
        return true;
    }

    /** Returns the byte footprint of a value when encoded by writeFields. */
    private static int encodedByteSize(Object value) {
        int size = 0;
        for (java.lang.reflect.Field f : value.getClass().getDeclaredFields()) {
            if (java.lang.reflect.Modifier.isStatic(f.getModifiers())) {
                continue;
            }
            size += sizeOfType(f.getType());
        }
        return size;
    }

    /**
     * Builds candidate combinations with bit-shift awareness for enum params.
     * When an enum parameter's getValue() is shifted left and OR'd into an int
     * field, we extract the shifted value from each int field and check if
     * any enum constant produces it. This covers transforms like
     * {@code _field = enum.getValue() << 28 | otherBits} by trying
     * {@code enum.fromValue(fieldValue >>> shift)} for common shift amounts.
     */
    private static List<Object[]> constructorCombinationsWithBitShift(
            Class<?>[] paramTypes, Object[] fieldValues) {
        List<List<Object>> perParam = new ArrayList<>();
        long total = 1;
        for (int pi = 0; pi < paramTypes.length; pi++) {
            Class<?> paramType = paramTypes[pi];
            List<Object> options = new ArrayList<>();
            if (paramType.isEnum()) {
                Object[] constants = paramType.getEnumConstants();
                if (constants == null || constants.length == 0) {
                    return null;
                }
                // Try to extract enum value from int field values via bit shift.
                // Common shifts: 28, 24, 16, 8, 0 (direct).
                for (Object fv : fieldValues) {
                    if (fv instanceof Integer iv) {
                        for (int shift : new int[]{28, 24, 16, 8, 0}) {
                            int extracted = (iv >>> shift) & 0xF;
                            if (shift == 0) extracted = iv;
                            for (Object c : constants) {
                                if (c instanceof Enum<?> e) {
                                    try {
                                        int ev = (int) EnumHelper.readEnumValue(e);
                                        if (ev == extracted && !options.contains(e)) {
                                            options.add(e);
                                        }
                                    } catch (Exception ignored) { }
                                }
                            }
                        }
                    }
                }
                // If no bit-shift match, try all constants (bounded).
                if (options.isEmpty()) {
                    options.addAll(java.util.Arrays.asList(constants));
                }
            } else {
                for (Object fv : fieldValues) {
                    if (fv != null && boxedTypeMatches(paramType, fv) && !options.contains(fv)) {
                        options.add(fv);
                    }
                }
                if (options.isEmpty()) {
                    options.add(defaultPrimitiveValue(paramType));
                }
            }
            total *= options.size();
            if (total > MAX_PROBE_COMBINATIONS) {
                return null;
            }
            perParam.add(options);
        }
        List<Object[]> combinations = new ArrayList<>();
        buildCombinations(perParam, 0, new Object[paramTypes.length], combinations);
        return combinations;
    }

    /** Decodes one field value laid out by writeFields; null for types writeFields does not encode. */
    private static Object decodeFieldValue(ReadOnlySpan<Integer> span, int offset, Class<?> type) {
        if (type == int.class || type == Integer.class) {
            return readInt(span, offset);
        }
        if (type == long.class || type == Long.class) {
            long v = 0;
            for (int i = 0; i < 8 && offset + i < span.length(); i++) {
                v |= (long) (span.get(offset + i) & 0xFF) << (i * 8);
            }
            return v;
        }
        if (type == short.class) {
            int v = 0;
            for (int i = 0; i < 2 && offset + i < span.length(); i++) {
                v |= (span.get(offset + i) & 0xFF) << (i * 8);
            }
            return (short) v;
        }
        if (type == byte.class) {
            return (byte) (span.get(offset) & 0xFF);
        }
        if (type == char.class) {
            return (char) ((span.get(offset) & 0xFF) | ((span.get(offset + 1) & 0xFF) << 8));
        }
        if (type == boolean.class) {
            return span.get(offset) != 0;
        }
        return null;
    }

    /** Byte footprint writeFields advances per field type (must stay symmetric with it). */
    private static int sizeOfType(Class<?> type) {
        if (type == long.class || type == Long.class) {
            return 8;
        }
        if (type == short.class || type == char.class) {
            return 2;
        }
        if (type == byte.class || type == boolean.class) {
            return 1;
        }
        return 4;
    }

    private static boolean boxedTypeMatches(Class<?> paramType, Object boxedValue) {
        if (paramType == int.class || paramType == Integer.class) {
            return boxedValue instanceof Integer;
        }
        if (paramType == long.class || paramType == Long.class) {
            return boxedValue instanceof Long;
        }
        if (paramType == short.class) {
            return boxedValue instanceof Short;
        }
        if (paramType == byte.class) {
            return boxedValue instanceof Byte;
        }
        if (paramType == char.class) {
            return boxedValue instanceof Character;
        }
        if (paramType == boolean.class) {
            return boxedValue instanceof Boolean;
        }
        return false;
    }

    private static Object defaultPrimitiveValue(Class<?> paramType) {
        if (paramType == boolean.class) {
            return Boolean.FALSE;
        }
        if (paramType == char.class) {
            return (char) 0;
        }
        if (paramType == long.class) {
            return 0L;
        }
        if (paramType == short.class) {
            return (short) 0;
        }
        if (paramType == byte.class) {
            return (byte) 0;
        }
        return 0;
    }

    private static void readFields(Object instance, ReadOnlySpan<Integer> span) {
        int offset = 0;
        for (java.lang.reflect.Field f : instance.getClass().getDeclaredFields()) {
            if (java.lang.reflect.Modifier.isStatic(f.getModifiers())) {
                continue;
            }
            try {
                f.setAccessible(true);
                Class<?> t = f.getType();
                if (t == int.class) {
                    f.setInt(instance, readInt(span, offset));
                    offset += 4;
                } else if (t == long.class) {
                    long v = 0;
                    for (int i = 0; i < 8 && offset + i < span.length(); i++) {
                        v |= (long) (span.get(offset + i) & 0xFF) << (i * 8);
                    }
                    f.setLong(instance, v);
                    offset += 8;
                } else if (t == short.class) {
                    int v = 0;
                    for (int i = 0; i < 2 && offset + i < span.length(); i++) {
                        v |= (span.get(offset + i) & 0xFF) << (i * 8);
                    }
                    f.setShort(instance, (short) v);
                    offset += 2;
                } else if (t == byte.class) {
                    f.setByte(instance, (byte) (span.get(offset) & 0xFF));
                    offset += 1;
                } else if (t == char.class) {
                    char v = (char) ((span.get(offset) & 0xFF) | ((span.get(offset + 1) & 0xFF) << 8));
                    f.setChar(instance, v);
                    offset += 2;
                } else if (t == boolean.class) {
                    f.setBoolean(instance, span.get(offset) != 0);
                    offset += 1;
                } else {
                    offset += 4;
                }
            } catch (Exception e) {
                offset += 4;
            }
        }
    }

    private static int readInt(ReadOnlySpan<Integer> span, int offset) {
        int value = 0;
        int count = Math.min(4, span.length() - offset);
        for (int i = 0; i < count; i++) {
            value |= (span.get(offset + i) & 0xFF) << (i * 8);
        }
        return value;
    }

    /**
     * Mirrors {@code MemoryMarshal.Cast<byte, int>(Span<byte>)} — the port reuses
     * {@code Span<Integer>} for both byte- and int-backed spans, so a byte-backed
     * span must be reinterpreted as 4-byte little-endian elements; without that,
     * writes such as {@code newDbInts[i] -= locationOffset} in
     * {@code JsonDocument.MetadataDb.CopySegment} only touch single bytes and corrupt
     * the copied rows. Spans that are not byte-backed are already element-typed.
     */
    public static Span<Integer> cast(Span<Integer> span) {
        return Span.castToInt32(span);
    }

    /** Mirrors MemoryMarshal.Write&lt;T&gt;(Span&lt;byte&gt;, ref T) — writes the value as little-endian bytes. */
    public static <T> void write(Span<Integer> span, ObjectHolder<T> value) {
        writeValue(span, value.value);
    }

    /** Mirrors MemoryMarshal.Write&lt;int&gt;(Span&lt;byte&gt;, ref int). */
    public static void write(Span<Integer> span, IntHolder value) {
        writeValue(span, value.value);
    }

    /** Mirrors MemoryMarshal.Write&lt;long&gt;(Span&lt;byte&gt;, ref long). */
    public static void write(Span<Integer> span, LongHolder value) {
        writeValue(span, value.value);
    }

    private static void writeValue(Span<Integer> span, Object value) {
        if (value instanceof Number n) {
            long lv = n.longValue();
            int size = 8;
            if (value instanceof Integer || value instanceof Float) {
                size = 4;
            } else if (value instanceof Short) {
                size = 2;
            } else if (value instanceof Byte) {
                size = 1;
            }
            for (int i = 0; i < size && i < span.length(); i++) {
                span.set(i, (int) ((lv >>> (i * 8)) & 0xFF));
            }
            return;
        }
        if (value != null) {
            writeFields(value, span);
            return;
        }
        for (int i = 0; i < span.length(); i++) {
            span.set(i, 0);
        }
    }

    /** Writes a struct's fields (declaration order) as little-endian bytes, mirroring C# MemoryMarshal.Write&lt;T&gt;. */
    private static void writeFields(Object value, Span<Integer> span) {
        int offset = 0;
        for (java.lang.reflect.Field f : value.getClass().getDeclaredFields()) {
            if (java.lang.reflect.Modifier.isStatic(f.getModifiers())) {
                continue;
            }
            try {
                f.setAccessible(true);
                Class<?> t = f.getType();
                if (t == int.class) {
                    int v = f.getInt(value);
                    for (int i = 0; i < 4 && offset + i < span.length(); i++) {
                        span.set(offset + i, (v >>> (i * 8)) & 0xFF);
                    }
                    offset += 4;
                } else if (t == long.class) {
                    long v = f.getLong(value);
                    for (int i = 0; i < 8 && offset + i < span.length(); i++) {
                        span.set(offset + i, (int) ((v >>> (i * 8)) & 0xFF));
                    }
                    offset += 8;
                } else if (t == short.class) {
                    short v = f.getShort(value);
                    for (int i = 0; i < 2 && offset + i < span.length(); i++) {
                        span.set(offset + i, (v >>> (i * 8)) & 0xFF);
                    }
                    offset += 2;
                } else if (t == byte.class) {
                    span.set(offset, f.getByte(value) & 0xFF);
                    offset += 1;
                } else if (t == char.class) {
                    char v = f.getChar(value);
                    span.set(offset, v & 0xFF);
                    span.set(offset + 1, (v >>> 8) & 0xFF);
                    offset += 2;
                } else if (t == boolean.class) {
                    span.set(offset, f.getBoolean(value) ? 1 : 0);
                    offset += 1;
                } else if (t == Integer.class) {
                    int v = f.getInt(value);
                    for (int i = 0; i < 4 && offset + i < span.length(); i++) {
                        span.set(offset + i, (v >>> (i * 8)) & 0xFF);
                    }
                    offset += 4;
                } else if (t == Long.class) {
                    long v = f.getLong(value);
                    for (int i = 0; i < 8 && offset + i < span.length(); i++) {
                        span.set(offset + i, (int) ((v >>> (i * 8)) & 0xFF));
                    }
                    offset += 8;
                } else {
                    offset += 4;
                }
            } catch (IllegalAccessException e) {
                offset += 4;
            }
        }
    }
}
